<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { applicationService, loadApplicationExamples, statusLabels, type Application, type ApplicationStatus } from '@/services/applications'
import AppModal from '@/components/AppModal.vue'
import { demoMode } from '@/services/quality'
const examplesOpen=ref(false)
async function examples(){try{loadApplicationExamples();examplesOpen.value=false;await load()}catch(e){error.value=(e as Error).message}}
const applications = ref<Application[]>([]); const loading = ref(true); const error = ref(''); const notice = ref(''); const filter = ref('all'); const search = ref(''); const selected = ref<Application | null>(null); const decision = ref<ApplicationStatus>('under_review'); const note = ref(''); const busy = ref(false)
const filtered = computed(() => applications.value.filter(a => (filter.value === 'all' || a.status === filter.value) && `${a.name} ${a.city} ${a.email}`.toLowerCase().includes(search.value.toLowerCase())))
async function load() { loading.value = true; error.value = ''; try { applications.value = await applicationService.list(true) } catch(e) { error.value = (e as Error).message } finally { loading.value = false } }
function inspect(a: Application) { selected.value = a; note.value = ''; decision.value = a.status === 'pending' ? 'under_review' : 'active'; error.value = ''; notice.value = '' }
async function submit() {
 if (!selected.value) return
 if (['rejected','corrections_requested'].includes(decision.value) && !note.value.trim()) { error.value = 'Un motif est obligatoire pour cette décision.'; return }
 busy.value = true; error.value = ''
 try { await applicationService.decide(selected.value.id, decision.value, note.value); selected.value = null; notice.value = 'Décision enregistrée. Le suivi du demandeur est mis à jour.'; await load() }
 catch(e) { error.value = (e as Error).message } finally { busy.value = false }
}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading compact"><div><p class="eyebrow">ESPACE BEG · INSTRUCTION</p><h1>Les officines,<br><span class="accent-serif">bien accompagnées.</span></h1><p class="page-subtitle">Examinez les demandes avant d’ouvrir un espace métier.</p></div><div class="module-links"><button v-if="demoMode" class="button secondary" @click="examplesOpen=true">Charger des dossiers fictifs</button><button class="button secondary" :disabled="loading || busy" @click="load">Actualiser</button></div></div><p v-if="demoMode" class="alert">Vue BEG simulée, réservée aux essais du parcours. En mode API, un administrateur plateforme est requis.</p><p v-if="error && !selected" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><section class="panel"><div class="table-toolbar"><label>État du dossier<select v-model="filter"><option value="all">Tous les dossiers</option><option v-for="(label, status) in statusLabels" :key="status" :value="status">{{ label }}</option></select></label><label class="search-field"><input v-model="search" type="search" placeholder="Officine, ville, e-mail…" aria-label="Rechercher un dossier" /></label></div><p v-if="loading" class="loading">Chargement des inscriptions…</p><div v-else-if="!filtered.length" class="empty-state"><h2>Aucun dossier à afficher</h2><p>Les demandes d’ouverture apparaîtront ici après leur soumission.</p><RouterLink v-if="demoMode" class="button primary" to="/register">Simuler une inscription</RouterLink></div><div v-else class="table-scroll"><table><thead><tr><th>OFFICINE</th><th>VILLE</th><th>DEMANDEUR</th><th>ÉTAT</th><th>INSTRUCTION</th></tr></thead><tbody><tr v-for="a in filtered" :key="a.id"><td><strong>{{ a.name }}</strong><small class="table-subtitle">Dossier #{{ a.id }}</small></td><td>{{ a.city }}</td><td>{{ a.email }}</td><td><span class="status-badge" :class="a.status">{{ statusLabels[a.status] }}</span></td><td><button class="button secondary" @click="inspect(a)">Consulter</button></td></tr></tbody></table></div><div class="panel-foot">{{ filtered.length }} dossier(s) affiché(s) · 200 dossiers maximum en mode API</div></section><AppModal :model-value="!!selected" :title="selected?.name || 'Dossier officine'" :eyebrow="`DOSSIER #${selected?.id || ''}`" :busy="busy" size="wide" @update:model-value="selected = null"><div v-if="selected" class="form-body"><p v-if="error" role="alert" class="alert error">{{ error }}</p><dl class="application-summary"><dt>Adresse</dt><dd>{{ selected.address }}, {{ selected.city }}</dd><dt>Contact</dt><dd>{{ selected.email }} · {{ selected.phone }}</dd><dt>Fonction déclarée</dt><dd>{{ selected.applicant_function }}</dd><dt>Dernier message</dt><dd>{{ selected.review_note || 'Aucun message' }}</dd></dl><form v-if="['pending','under_review'].includes(selected.status)" class="correction-form" @submit.prevent="submit"><label>Décision<select v-model="decision"><option v-if="selected.status === 'pending'" value="under_review">Commencer l’instruction</option><template v-else><option value="active">Activer l’espace</option><option value="corrections_requested">Demander des compléments</option><option value="rejected">Refuser avec motif</option></template></select></label><label>Message au demandeur {{ ['corrections_requested', 'rejected'].includes(decision) ? '*' : '(facultatif)' }}<textarea v-model="note" rows="3" maxlength="2000" :required="['corrections_requested','rejected'].includes(decision)" placeholder="Précisez les compléments attendus ou le motif de la décision." /></label><p v-if="decision === 'active'" class="field-hint">Cette activation ouvre uniquement le module qualité au demandeur. Elle ne certifie aucune habilitation clinique et ne vaut pas validation sanitaire.</p><button class="button primary self-start" :disabled="busy">{{ busy ? 'Enregistrement…' : 'Enregistrer la décision' }}</button></form><p v-else class="field-hint">Aucune nouvelle décision possible dans cet état. Un dossier à compléter doit être soumis à nouveau par son demandeur.</p></div><template #footer><button class="button secondary" :disabled="busy" @click="selected = null">Fermer</button></template></AppModal><AppModal v-model="examplesOpen" title="Charger trois dossiers fictifs ?" size="small"><div class="form-body"><p>Un dossier soumis, un dossier en instruction et un dossier à compléter seront ajoutés, sans écraser les demandes existantes. Aucun compte ni accès réel ne sera créé.</p></div><template #footer><button class="button secondary" @click="examplesOpen=false">Annuler</button><button class="button primary" @click="examples">Charger les exemples</button></template></AppModal></div></template>
